////////////////////////////////////////////////////////////////////////////////
// ●カスタマイズ情報のロード
////////////////////////////////////////////////////////////////////////////////
function init_custmize(name) {
  cols = undefined;
  opts = undefined;
  css_text = '';
  submit_btn.prop('disabled', true);
  $.ajax({
	url: adiary.myself + '?design/theme_colors&name=' + name,
	dataType: 'json',
	success: function(data){
		if (data.error || !data._css_text)
			return custom_form_empty();
		// 値保存
		css_text = data._css_text;
		delete data['_css_text'];
		var data2 = data._options;
		delete data['_options'];
		$('#custom-flag').val('1');

		// フォーム初期化
		init_custom_form(data, data2);
		submit_btn.prop('disabled', false);
	},
	error: custom_form_empty
        });
}
function custom_form_empty() {
	custom_form.hide();
	custom_opts.empty();
	custom_cols.empty();
	custom_detail.empty();
	input_cols  = $;
	select_opts = $;
	iframe_resize();
	$('#custom-flag').val('');
	submit_btn.prop('disabled', false);
}

////////////////////////////////////////////////////////////////////////////////
// ●カスタマイズフォーム設定
////////////////////////////////////////////////////////////////////////////////
function init_custom_form(data, data2) {
	cols = [];

	// データの取り出しと並べ替え
	var priority = ['base', 'main', 'art', 'wiki', 'footnote', 'border'];
	function get_priority(name) {
		if (name.indexOf( 'fix' ) == 0) return 1000;
		for(var i=0; i<priority.length; i++)
			if (name.indexOf( priority[i] ) == 0) return i;
		return 999;
	}
	var err='';
	for(var k in data) {
		if (k.substr(0,5) == '-err-') {
			err += '<div>' + data[k] + '</div>';
			continue;
		}
		// rgbaを変更
		var ma = data[k].match(/rgba\((\d+),(\d+),(\d+)/);	// rgba(255,255,255, 0.7)
		if (ma) {
			var val = '#';
			for(var i=1; i<4; i++)
				val += ('0' + (parseInt(ma[i])).toString(16)).substr(-2);
			data[k] = val;
			// console.log(val);
		}

		if (k.substr(-4) == '-cst') continue;
		if (k.substr(-4) == '-rel') continue;
		cols.push({name: k, val: data[k], priority: get_priority(k) });
	}
	if (err.length) adiary.show_error({html: err});
	cols = cols.sort(function(a, b) {
		if (a.priority < b.priority) return -1;
		if (a.priority > b.priority) return  1;
	        return (a.name < b.name) ? -1 : 1;
	});

	// フォームの生成
	custom_opts.empty();
	custom_cols.empty();
	custom_detail.empty();
	input_cols = [];
	rel_col = [];
	rel_pol = [];
	for(var i=0; i<cols.length; i++) {
		var name = cols[i].name;
		var val  = cols[i].val;
		var cval = data[name+'-cst'] || val;	// 初期値
		var rel  = data[name+'-rel'];		// 他に連動
		var msg  = name2msg(name);

		var span = $('<span>').addClass('color-box');
		span.text(msg);
		var inp = $('<input>').addClass('color-picker no-enter-submit').attr({
			type: 'text',
			id: 'inp-' + name,
			name: 'c_' + name,
			value: cval
		});
		inp.data('original', val);	// テーマ初期値
		inp.data('default_',cval);	// 現在の設定値（保存用）
		inp.data('default', cval);	// 現在の設定値
		inp.change( function(evt){
			update_css();
			var obj = $(evt.target);
			obj.ColorPickerSetColor( obj.val() );
		});
		(function(){
			var iobj = inp;		// クロージャ
			var n = name;
			iobj.data('onChange', function(hsb, hex, rgb) {
				iobj.data('val', '#' + hex);
				relation_colors(n);
				update_css();
				iobj.removeData('val');
			});
		})();
		span.append(inp);
		input_cols.push(inp);
		if (rel) rel_col[name] = rel;

		// 要素を追加
		var div = rel ? custom_detail : custom_cols;
		if (name.substr(0,3) == 'fix'
		 && name != 'fixbg' && name != 'fixmain' && name != 'fixartbg' && name != 'fixfont')
			div = custom_detail;
		div.append(span);
	}
	input_cols = $(input_cols);

	// color picker init
	adiary.dom_init( custom_form );

	// オプション選択生成
	opts = [];
	select_opts = [];
	if (data2) {
		for(var k in data2) {
			if (k.substr(-4) == '-cst') continue;
			opts.push({name: k, val: data2[k + '-cst'], list: data2[k] });
		}
		opts = opts.sort(function(a, b) {
		        return (a.name < b.name) ? -1 : 1;
		});

		for(var i=0; i<opts.length; i++) {
			var name = opts[i].name;
			if (name.match(/-\w+$/)) continue;

			var sel = $('<select>').attr('name', name);
			var title = data2[name + '-title'] || 'option';
			sel.append($('<option>').attr('value','').text( name2msg(title) ));
			sel.change( function(evt){
				update_css();
			});
			var list = opts[i].list;
			var val  = opts[i].val || '';
			sel.data('default',  val);
			sel.data('original', data2[name + '-default'] || '');
			var h = {};
			for(var j=0; j<list.length; j++) {
				if (h[list[j]]) continue;	// 重複チェック
				h[list[j]]=1;

				var n = name2msg( list[j] );	// 翻訳
				var o = $('<option>')
					.attr('value', list[j])
					.text(n);
				if (list[j] == val) o.prop('selected', true);
				sel.append(o);
			}
			custom_opts.append( sel );
			select_opts.push( sel );
		}
		select_opts = $(select_opts);
	}
	if (cols.length < 1) color_bar.hide();
			else color_bar.show();
	custom_form.show();
	iframe_resize();

	// すべてロードされる前に送信されることがある。
	custom_form.append($('<input>').attr({
		type:	'hidden',
		name:	'custom_flag',
		value:	1
	}));

	// 色式デバッグ用（テーマ開発者向け）
	relation_colors('', 1);
}

////////////////////////////////////////////////////////////////////////////////
// ●値連動処理
////////////////////////////////////////////////////////////////////////////////
function relation_colors(name, test) {
	if (!test && detail_mode.prop('checked')) return;
	for(var k in rel_col) {
		var col = rel_col[k];
		var v;
		if (col.substr(0,5) == 'auto:')
			v = automatic(k, col.substr(5));
		else {
			var src = $('#inp-' + col);
			v = src.data('val') || src.val();
		}
		// console.log(k + ' = ' + v + ' = ' + col );
		if (!v) {
			adiary.show_error('#css-exp-error', {s: rel_col[k]});
			continue;
		}
		var obj = $('#inp-' + k);
		set_color(obj, v);
	}
}

