var CSS_ReInit;
setInterval(function(){
	if (!CSS_ReInit) return;
	CSS_ReInit = false;
	iframe[0].contentWindow.adiary.css_init();
},300);

function update_css() {
	var col = {};
	input_cols.each(function(idx,dom){
		var obj = $(dom);
		var val = obj.data('val') || obj.val();
		if (val.match(/#[0-9A-Fa-f]{6}/))
			col[ obj.attr('name').substr(2) ] = val;
	});
	var opt = {};
	select_opts.each(function(idx,dom){
		var obj = $(dom);
		opt[ obj.attr('name') ] = obj.val();
	});
	var lines = css_text.split("\n");
	var in_opt;
	var opt_sel;
	for(var i=0; i<lines.length; i++) {
		var x = lines[i];
		// 画像ファイル
		var ma = x.match(/(.*?)url\s*\(\s*(['"])([^'"]+)\2\s*\)(.*)/i);
		if (ma) {
			var file = ma[3];
			file = file.replace('./', '');
			if (file.match(/^[\w-]+(?:\.[\w-]+)*$/))
				x = ma[1] + "url('" + theme_dir + current_theme + '/' + file + "')" + ma[4];
			lines[i] = x;
		}
		// オプション
		var ma = in_opt || x.match(/\$(option\d*)=(.+)/);
		if (ma) {
			if (!in_opt) {
				in_opt  = true;
				opt_sel = (opt[ ma[1] ] == ma[2]);
				lines[i]='';
			} else if (ma = x.match(/(.*?)\s*\*\//)) {
				in_opt = false;
				x = ma[1];
				ma = x.match(/^(.*[;}])/);
				if (ma) x=ma[1];
				   else x='';
				lines[i]=x;
			}
			if (!opt_sel) lines[i]='';
			continue;
		}

		// 色カスタム
		var ma = x.match(/\$c=(\w+)/);
		if (!ma) continue;
		lines[i] = x.replace(/#[0-9A-Fa-f]+/,     col[ ma[1] ])
		            .replace(/rgba\(\d+,\d+,\d+/, RGBtoRGBA( col[ ma[1] ] ));
	}
	var new_css = lines.join("\n");
	if_css.html( new_css );

	// CSSによる設定反映
	// iframe[0].contentWindow.adiary.css_init();
	CSS_ReInit = true;
}

function RGBtoRGBA(rgb) {
	var ma = rgb.match(/#([0-9A-Fa-f]{2})([0-9A-Fa-f]{2})([0-9A-Fa-f]{2})/);
	if (!ma) return "rgba(0,0,0";

	var r = parseInt('0x' + ma[1]);
	var g = parseInt('0x' + ma[2]);
	var b = parseInt('0x' + ma[3]);
	return 'rgba(' + r + ',' + g + ',' + b;
}

