function set_color(obj, rgb) {
	obj.val( rgb );
	if (obj.ColorPickerSetColor) {
		var prev = obj.prev();
		if (prev.hasClass('colorbox'))
			prev.css('background-color', rgb);
		obj.ColorPickerSetColor( rgb );
	}
}

